#include <iostream>
#include <mutex>
#include <optional>
#include <string>
#include <unordered_map>
class Cache {
public:
    void put(std::string key, int value) { std::lock_guard lock(m_); values_[std::move(key)] = value; }
    std::optional<int> get(const std::string& key) const {
        std::lock_guard lock(m_); auto it = values_.find(key);
        if (it == values_.end()) return std::nullopt;
        return it->second;
    }
private: mutable std::mutex m_; std::unordered_map<std::string, int> values_;
};
int main() { Cache cache; cache.put("answer", 42); std::cout << cache.get("answer").value_or(0) << '\n'; }
